    41→        let zone_width = available_width / zone_count as f32;
    42→
    43→        let (response, painter) = ui.allocate_painter(
    44→            Vec2::new(available_width, bar_height + 20.0),
    45→            egui::Sense::hover(),
    46→        );
    47→
    48→        let rect = response.rect;
    49→        let bar_rect = Rect::from_min_size(rect.min, Vec2::new(available_width, bar_height));
    50→
    51→        // Draw zone color bars
    52→        for zone in 1..=zone_count {
    53→            let zone_x = rect.min.x + (zone - 1) as f32 * zone_width;
    54→            let zone_rect = Rect::from_min_size(
    55→                Pos2::new(zone_x, bar_rect.min.y),
    56→                Vec2::new(zone_width, bar_height),
    57→            );
    58→
    59→            let color = to_color32(&POWER_ZONE_COLORS[(zone - 1) as usize]);
    60→
    61→            // Dim zones that are not current
    62→            let fill_color = if current_zone == Some(zone) {
    63→                color
    64→            } else {
    65→                color.linear_multiply(0.3)
    66→            };
    67→
    68→            painter.rect_filled(zone_rect, 0.0, fill_color);
    69→
    70→            // Draw zone number
    71→            let text_pos = zone_rect.center();
    72→            let text_color = if current_zone == Some(zone) {
    73→                Color32::WHITE
    74→            } else {
    75→                Color32::from_gray(100)
    76→            };
    77→
    78→            painter.text(
    79→                text_pos,
    80→                egui::Align2::CENTER_CENTER,
    81→                format!("Z{}", zone),
    82→                egui::FontId::proportional(12.0),
    83→                text_color,
    84→            );
    85→        }
    86→
    87→        // Draw current zone label below bar
    88→        if let Some(zone) = current_zone {
    89→            let zone_name = if let Some(zones) = zones {
