    91→            } else {
    92→                Some(default_power_zone_name(zone))
    93→            };
    94→
    95→            if let Some(name) = zone_name {
    96→                let label_y = bar_rect.max.y + 4.0;
    97→                let zone_color = to_color32(&POWER_ZONE_COLORS[(zone - 1) as usize]);
    98→
    99→                painter.text(
