   138→    }
   139→
   140→    /// Update FTP and recalculate zones.
   141→    pub fn set_ftp(&mut self, ftp: u16) {
   142→        self.ftp = ftp;
   143→        self.power_zones = Some(PowerZones::from_ftp(ftp));
   144→    }
   145→
   146→    /// Process a sensor reading and update metrics.
   147→    pub fn process(&mut self, reading: &SensorReading) -> &AggregatedMetrics {
   148→        let now = reading.timestamp;
   149→
   150→        // Start timer on first reading
   151→        if self.start_time.is_none() {
   152→            self.start_time = Some(now);
   153→        }
   154→
   155→        // Process power
   156→        if let Some(power) = reading.power_watts {
   157→            if let Some(filtered_power) = self.power_filter.filter(power) {
   158→                // Update rolling averages
   159→                self.current_metrics.power_instant = Some(filtered_power);
   160→                self.current_metrics.power_3s_avg = self.power_3s.add(filtered_power);
   161→                self.current_metrics.power_30s_avg = self.power_30s.add(filtered_power);
   162→
   163→                // Update NP
   164→                self.current_metrics.normalized_power = self.np_calculator.add(filtered_power);
   165→
   166→                // Update average and max
   167→                self.power_sum += filtered_power as u64;
   168→                self.power_count += 1;
   169→                self.max_power = self.max_power.max(filtered_power);
   170→
   171→                // Calculate power zone
   172→                if let Some(zones) = &self.power_zones {
   173→                    self.current_metrics.power_zone = Some(
   174→                        zones.get_zone(self.current_metrics.power_3s_avg.unwrap_or(filtered_power)),
   175→                    );
   176→                }
   177→
   178→                // Update calories (kJ ≈ kcal for cycling)
   179→                // 1 watt for 1 second = 1 joule
   180→                // Accumulate joules, divide by 1000 for kJ, ≈ kcal
   181→                self.total_calories = (self.power_sum / 1000) as u32;
   182→            }
   183→        }
   184→
   185→        // Process heart rate
   186→        if let Some(hr) = reading.heart_rate_bpm {
   187→            self.current_metrics.heart_rate = Some(hr);
   188→
   189→            if let Some(zones) = &self.hr_zones {
   190→                self.current_metrics.hr_zone = Some(zones.get_zone(hr));
   191→            }
   192→        }
   193→
   194→        // Process cadence
   195→        if let Some(cadence) = reading.cadence_rpm {
   196→            self.current_metrics.cadence = Some(cadence);
   197→
   198→            // Calculate cadence zone
   199→            if let Some(zones) = &self.cadence_zones {
   200→                self.current_metrics.cadence_zone = Some(zones.get_zone(cadence));
   201→            }
   202→        }
   203→
   204→        // Process speed
   205→        if let Some(speed) = reading.speed_kmh {
   206→            self.current_metrics.speed = Some(speed);
   207→        }
   208→
   209→        // Process distance
   210→        if let Some(delta) = reading.distance_delta_m {
   211→            self.total_distance += delta as f64;
   212→        }
   213→
   214→        // Update aggregated metrics
   215→        self.current_metrics.timestamp = Some(now);
   216→        self.current_metrics.distance = self.total_distance;
   217→        self.current_metrics.calories = self.total_calories;
   218→
   219→        if let Some(start) = self.start_time {
   220→            self.current_metrics.elapsed_time = now.duration_since(start);
   221→        }
   222→
   223→        // Calculate TSS and IF
   224→        if let Some(np) = self.current_metrics.normalized_power {
   225→            if self.ftp > 0 {
   226→                let if_value = np as f32 / self.ftp as f32;
   227→                self.current_metrics.intensity_factor = Some(if_value);
   228→
   229→                let duration_hours = self.current_metrics.elapsed_time.as_secs_f32() / 3600.0;
   230→                let tss = duration_hours * if_value * if_value * 100.0;
   231→                self.current_metrics.tss = Some(tss);
   232→            }
   233→        }
   234→
   235→        &self.current_metrics
   236→    }
