   856→    fn test_zone_tracker_power_zone_change() {
   857→        let power_zones = PowerZones::from_ftp(200);
   858→        let mut tracker = ZoneTracker::new(power_zones);
   859→        tracker.set_debounce_secs(0); // Disable debounce for testing
   860→
   861→        // First update sets initial zone (no event emitted)
   862→        tracker.update_power(100); // Zone 1
   863→        assert_eq!(tracker.current_power_zone(), 1);
   864→        assert!(!tracker.has_pending_events());
   865→
   866→        // Zone change should emit event
   867→        tracker.update_power(200); // Zone 4 (Threshold)
   868→        assert_eq!(tracker.current_power_zone(), 4);
   869→        assert!(tracker.has_pending_events());
   870→
   871→        let events = tracker.take_events();
   872→        assert_eq!(events.len(), 1);
   873→        match &events[0] {
   874→            ZoneEvent::PowerZoneChange {
   875→                previous_zone,
   876→                new_zone,
   877→                zone_name,
   878→            } => {
   879→                assert_eq!(*previous_zone, 1);
   880→                assert_eq!(*new_zone, 4);
   881→                assert_eq!(zone_name, "Threshold");
   882→            }
   883→            _ => panic!("Expected PowerZoneChange event"),
   884→        }
   885→    }
